contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function invariant(address otherRecipient) public {
        bool ok1; c.withdrawAll(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok1 = false; } else { ok1 = true; }
        bool ok2; c.withdrawAll(otherRecipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) { ok2 = false; } else { ok2 = true; }
        assert(ok1 == ok2);
    }

    receive() external payable {}
    fallback() external payable {}
}

