// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _invariant(address otherRecipient) internal {
        bool ok1;
        try c.withdrawAll(address(this)) { ok1 = true; } catch { ok1 = false; }
        bool ok2;
        try c.withdrawAll(otherRecipient) { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok1 == ok2);
    }

    function testFuzz_invariant(address otherRecipient) public {
        vm.assume(otherRecipient.code.length == 0 && uint160(otherRecipient) > 0xffff && otherRecipient != address(this) && otherRecipient != address(c) && otherRecipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && otherRecipient != 0x000000000000000000636F6e736F6c652e6c6f67 && otherRecipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && otherRecipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _invariant(otherRecipient);
    }

    receive() external payable {}

    fallback() external payable {}
}
